        G[k] = [[int(x) for x in r] for r in rows]

print("Loaded grids:", sorted(G.keys()))
for k in G:
    print(f"\n=== {k} ({len(G[k][0])}x{len(G[k])}) ===")
    for i, grid in enumerate(G[k]):
        print(f"  Grid {i}:")
        for row in grid:
            print("    ", row[:10]+"..." if len(row) > 10 else "    ", row)

